using CsCom.CodeGeneration;
using CsCom.LibrarySets;
using CsCom.TypeLibraries;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;

namespace CsCom.Output;

/// <summary>
/// Creates and updates C# projects with the interop types of type libraries or interop assemblies, which are generated by
/// <see cref="LibrarySetGenerator"/>: each library into its own namespace.
/// </summary>
public sealed partial class ProjectGenerator
{
    private readonly InteropPipeline _pipeline;
    private readonly ILoggerFactory _loggerFactory;
    private readonly ILogger _logger;

    /// <summary>
    /// Initializes a new instance of the <see cref="ProjectGenerator"/> class.
    /// </summary>
    public ProjectGenerator(InteropPipeline pipeline, ILoggerFactory? loggerFactory = null)
    {
        _pipeline = pipeline;
        _loggerFactory = loggerFactory ?? NullLoggerFactory.Instance;
        _logger = _loggerFactory.CreateLogger<ProjectGenerator>();
    }

    /// <summary>
    /// Creates a new project.
    /// </summary>
    /// <returns>The path to the project file.</returns>
    public string CreateProject(CreateProjectRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);

        // The directory is checked before the generation when it is known.
        if ((request.OutputDirectory ?? request.Name) is { } knownDirectory)
        {
            ThrowIfProjectExists(Path.GetFullPath(knownDirectory));
        }

        var generated = Generate(request);
        string directory = Path.GetFullPath(request.OutputDirectory ?? generated.Manifest.Name);
        ThrowIfProjectExists(directory);
        var manifest = generated.Manifest with
        {
            Configurations = ToRelativePaths(directory, generated.Manifest.Configurations),
            ReferencePaths = ToRelativePaths(directory, generated.Manifest.ReferencePaths),
        };
        string projectPath = WriteProject(directory, manifest, generated.Documents, generated.RootNamespace, request.PackageSource, request.GlobalPackagesFolder);
        LogProjectCreated(projectPath);
        return projectPath;
    }

    /// <summary>
    /// Regenerates the C# files of a project created with <see cref="CreateProject"/>.
    /// </summary>
    /// <returns>The path to the project directory.</returns>
    public string UpdateProject(UpdateProjectRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);

        string directory = Path.GetFullPath(request.ProjectDirectory ?? Environment.CurrentDirectory);
        var manifest = CsComManifest.Read(directory);
        var sources = request.Sources is { Count: > 0 } requested ? requested : manifest.GetSources();
        if (sources.Count == 0)
        {
            throw new CsComException($"'{Path.Combine(directory, CsComManifest.FileName)}' does not record the sources of the project.");
        }

        ValidateSingleSourceOptions(sources.Count, request.Namespace, string.IsNullOrEmpty(request.ConfigurationPath) ? null : request.ConfigurationPath);
        int languageVersion = ValidateLanguageVersion(request.LanguageVersion ?? manifest.LanguageVersion, manifest.TargetFrameworks);
        IReadOnlyList<string>? referencePaths = request.ReferencePaths switch
        {
            null => manifest.ReferencePaths?.Select(path => Path.GetFullPath(Path.Combine(directory, path))).ToList(),
            [] => null,
            var paths => paths.Select(Path.GetFullPath).ToList(),
        };

        // The namespace and the configuration file of the single source of the projects of earlier versions apply to it, and
        // are then recorded by library name.
        var namespaces = Merge(manifest.Namespaces, request.Namespaces);
        string? @namespace = request.Namespace ?? (sources.Count == 1 ? manifest.Namespace : null);
        Dictionary<string, string> configurations;
        string? configuration;
        if (request.ConfigurationPath == string.Empty)
        {
            configurations = new(StringComparer.OrdinalIgnoreCase);
            configuration = null;
        }
        else
        {
            configurations = Merge(
                manifest.Configurations?.ToDictionary(static p => p.Key, p => Path.GetFullPath(Path.Combine(directory, p.Value))),
                request.ConfigurationPaths.ToDictionary(static p => p.Key, static p => p.Value.Length == 0 ? string.Empty : Path.GetFullPath(p.Value)));
            configuration = request.ConfigurationPath is { } path ? Path.GetFullPath(path)
                : sources.Count == 1 && manifest.Configuration is { } recorded ? Path.GetFullPath(Path.Combine(directory, recorded))
                : null;
        }

        var settings = manifest with
        {
            ToolVersion = ToolInfo.Version,
            LanguageVersion = languageVersion,
            SingleFile = request.SingleFile ?? manifest.SingleFile,
            Marshalling = request.Marshalling.Apply(manifest.Marshalling),
            EventStyle = request.EventStyle ?? manifest.EventStyle,
            StructProperties = request.StructProperties ?? manifest.StructProperties,
            OverloadsForDefaultValues = request.OverloadsForDefaultValues ?? manifest.OverloadsForDefaultValues,
            ReferencePaths = referencePaths,
        };
        var generated = Generate(settings, CreateReferences(sources, referencePaths ?? [], @namespace, configuration), namespaces, configurations, manifest.Name);
        GeneratedFiles.Write(directory, generated.Documents);

        string? projectPath = FindProjectFile(directory, manifest.Name);
        if (projectPath is null)
        {
            LogProjectFileNotFound(directory);
        }
        else if (ProjectFile.Update(projectPath, languageVersion, ToolInfo.Version))
        {
            LogProjectFileUpdated(projectPath);
        }

        var updated = generated.Manifest with
        {
            Configurations = ToRelativePaths(directory, generated.Manifest.Configurations),
            ReferencePaths = ToRelativePaths(directory, referencePaths),
        };
        updated.Write(directory);
        LogProjectUpdated(directory, generated.Documents.Count);
        return directory;
    }

    /// <summary>
    /// Generates the code of a new project or assembly: validates the request, generates the libraries and completes the
    /// settings with the name, the sources, and the namespaces and the configuration files by library name.
    /// </summary>
    internal GeneratedProject Generate(OutputRequest request)
    {
        var settings = ResolveSettings(request);
        var namespaces = Merge(null, request.Namespaces);
        var configurations = Merge(null, request.ConfigurationPaths.ToDictionary(static p => p.Key, static p => Path.GetFullPath(p.Value)));
        string? configuration = string.IsNullOrEmpty(request.ConfigurationPath) ? null : Path.GetFullPath(request.ConfigurationPath);
        var references = CreateReferences(request.Sources, settings.ReferencePaths ?? [], request.Namespace, configuration);
        return Generate(settings, references, namespaces, configurations, request.Name);
    }

    /// <summary>
    /// Writes a project with the generated files into the directory.
    /// </summary>
    internal string WriteProject(
        string directory,
        CsComManifest manifest,
        IReadOnlyList<GeneratedDocument> documents,
        string rootNamespace,
        string? packageSource,
        string? globalPackagesFolder,
        IReadOnlyDictionary<string, string>? extraProperties = null)
    {
        Directory.CreateDirectory(directory);
        GeneratedFiles.Write(directory, documents);
        LogFilesGenerated(documents.Count, Path.Combine(directory, GeneratedFiles.FolderName));

        string? runtimePackageVersion = ToolInfo.Version;
        if (manifest.SupportCode == SupportCodeMode.Package && ProjectFile.FindCentralPackageManagement(directory) is { } packagesProps)
        {
            runtimePackageVersion = null;
            LogCentralPackageManagement(packagesProps, ProjectFile.RuntimePackageId, ToolInfo.Version);
        }

        string projectPath = Path.Combine(directory, manifest.Name + ".csproj");
        File.WriteAllText(projectPath, ProjectFile.Create(manifest, rootNamespace, runtimePackageVersion, extraProperties));
        if (packageSource is not null || globalPackagesFolder is not null)
        {
            File.WriteAllText(
                Path.Combine(directory, "nuget.config"),
                ProjectFile.CreateNuGetConfig(packageSource is null ? null : Path.GetFullPath(packageSource), globalPackagesFolder is null ? null : Path.GetFullPath(globalPackagesFolder)));
        }

        manifest.Write(directory);
        return projectPath;
    }

    /// <summary>
    /// Validates the options of a new project or assembly and applies the defaults; the name, the sources, the namespaces and
    /// the configuration files are set by <see cref="Generate(OutputRequest)"/>. The reference paths are recorded with their full paths.
    /// </summary>
    internal CsComManifest ResolveSettings(OutputRequest request)
    {
        if (request.Sources.Count == 0)
        {
            throw new CsComException("No type library or interop assembly is specified.");
        }

        if (request.Sources.Count > 1 && request.Name is null)
        {
            throw new CsComException("The name of the project or assembly must be specified when there are several sources.");
        }

        ValidateSingleSourceOptions(request.Sources.Count, request.Namespace, string.IsNullOrEmpty(request.ConfigurationPath) ? null : request.ConfigurationPath);
        if (request.Name is not null)
        {
            ValidateName(request.Name);
        }

        var targetFrameworks = request.TargetFrameworks.Count > 0
            ? request.TargetFrameworks.Distinct(StringComparer.OrdinalIgnoreCase).ToList()
            : [TargetFrameworks.Default];
        foreach (string targetFramework in targetFrameworks)
        {
            if (!TargetFrameworks.TryGetMajorVersion(targetFramework, out _, out string? error))
            {
                throw new CsComException(error);
            }

            if (!TargetFrameworks.IsWindowsSpecific(targetFramework))
            {
                LogNotWindowsSpecific(targetFramework);
            }
        }

        var runtimeIdentifiers = request.RuntimeIdentifiers
            .Where(static r => !string.Equals(r, "AnyCPU", StringComparison.OrdinalIgnoreCase))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        foreach (string runtimeIdentifier in runtimeIdentifiers.Where(static r => !r.StartsWith("win", StringComparison.OrdinalIgnoreCase)))
        {
            LogNotWindowsRuntime(runtimeIdentifier);
        }

        return new CsComManifest
        {
            ToolVersion = ToolInfo.Version,
            Name = request.Name ?? string.Empty,
            TargetFrameworks = targetFrameworks,
            RuntimeIdentifiers = runtimeIdentifiers,
            LanguageVersion = ValidateLanguageVersion(request.LanguageVersion, targetFrameworks),
            SingleFile = request.SingleFile,
            SupportCode = request.SupportCode,
            Marshalling = request.Marshalling,
            EventStyle = request.EventStyle,
            StructProperties = request.StructProperties,
            OverloadsForDefaultValues = request.OverloadsForDefaultValues,
            ReferencePaths = request.ReferencePaths.Count > 0 ? [.. request.ReferencePaths.Select(Path.GetFullPath)] : null,
        };
    }

    // Generates the libraries; a single source can have its own namespace and configuration file, which are recorded by the
    // name of its library, like those of several sources.
    private GeneratedProject Generate(
        CsComManifest settings,
        IReadOnlyList<LibrarySetReference> references,
        Dictionary<string, string> namespaces,
        Dictionary<string, string> configurations,
        string? name)
    {
        var options = new LibrarySetOptions
        {
            LanguageVersion = settings.LanguageVersion,
            SupportCode = settings.SupportCode,
            Marshalling = settings.Marshalling,
            EventStyle = settings.EventStyle,
            StructProperties = settings.StructProperties,
            OverloadsForDefaultValues = settings.OverloadsForDefaultValues,
            Namespaces = namespaces,
            ConfigurationPaths = configurations,
            SingleFile = settings.SingleFile,
        };
        var result = new LibrarySetGenerator(_pipeline, _loggerFactory).Generate(references, options);
        var first = result.Libraries[0];
        name ??= "Interop." + first.Name;
        ValidateName(name);
        if (references is [{ Namespace: { } @namespace }])
        {
            namespaces[first.Name] = @namespace;
        }

        if (references is [{ ConfigurationPath: { } configuration }])
        {
            configurations[first.Name] = configuration;
        }

        var manifest = settings with
        {
            Name = name,
            Sources = [.. references.Select(static r => TypeLibrarySource.Normalize(r.Source))],
            TypeLibrary = null,
            Namespace = null,
            Configuration = null,
            Namespaces = ToLibraryNames(namespaces, result.Libraries),
            Configurations = ToLibraryNames(configurations, result.Libraries),
        };
        var documents = settings.SingleFile ? [result.Documents.Single() with { RelativePath = name + ".cs" }] : result.Documents;
        return new GeneratedProject(manifest, documents, first.Namespace, result);
    }

    private static List<LibrarySetReference> CreateReferences(IReadOnlyList<string> sources, IReadOnlyList<string> referencePaths, string? @namespace, string? configuration) =>
        [.. sources.Select(source => new LibrarySetReference
        {
            Source = source,
            ReferencePaths = referencePaths,
            Namespace = sources.Count == 1 ? @namespace : null,
            ConfigurationPath = sources.Count == 1 ? configuration : null,
        })];

    // Applies the changes to the values recorded by library name; an empty value removes the recorded one.
    private static Dictionary<string, string> Merge(IReadOnlyDictionary<string, string>? recorded, IReadOnlyDictionary<string, string> changes)
    {
        var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var (name, value) in recorded ?? new Dictionary<string, string>())
        {
            values[name] = value;
        }

        foreach (var (name, value) in changes)
        {
            if (value.Length == 0)
            {
                values.Remove(name);
            }
            else
            {
                values[name] = value;
            }
        }

        return values;
    }

    // The values are recorded with the names of the libraries as they are, e.g. stdole for STDOLE; none when there are none.
    private static Dictionary<string, string>? ToLibraryNames(Dictionary<string, string> values, IReadOnlyList<LibrarySetLibrary> libraries) =>
        values.Count == 0 ? null : values.ToDictionary(
            pair => libraries.FirstOrDefault(l => string.Equals(l.Name, pair.Key, StringComparison.OrdinalIgnoreCase))?.Name ?? pair.Key,
            static pair => pair.Value,
            StringComparer.OrdinalIgnoreCase);

    private static void ValidateSingleSourceOptions(int sourceCount, string? @namespace, string? configuration)
    {
        if (sourceCount > 1 && @namespace is not null)
        {
            throw new CsComException(
                $"The namespace '{@namespace}' cannot be used with several sources: specify the namespaces of the libraries by their names, e.g. Excel=Office.Excel.");
        }

        if (sourceCount > 1 && configuration is not null)
        {
            throw new CsComException(
                $"The configuration file '{configuration}' cannot be used with several sources: specify the configuration files of the libraries by their names, e.g. Excel=excel.cscom.xml.");
        }
    }

    private static void ValidateName(string name)
    {
        if (string.IsNullOrWhiteSpace(name) || name.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0)
        {
            throw new CsComException($"'{name}' is not a valid project name.");
        }
    }

    private static void ThrowIfProjectExists(string directory)
    {
        if (Directory.Exists(directory)
            && (Directory.EnumerateFiles(directory, "*.csproj").Any() || File.Exists(Path.Combine(directory, CsComManifest.FileName))))
        {
            throw new CsComException($"The directory '{directory}' already contains a project. Use 'cscom project update' to update it.");
        }
    }

    // The paths recorded in cscom.json are relative to the project directory.
    private static List<string>? ToRelativePaths(string directory, IReadOnlyList<string>? paths) =>
        paths?.Select(path => Path.GetRelativePath(directory, path)).ToList();

    private static Dictionary<string, string>? ToRelativePaths(string directory, IReadOnlyDictionary<string, string>? paths) =>
        paths?.ToDictionary(static p => p.Key, p => Path.GetRelativePath(directory, p.Value), StringComparer.OrdinalIgnoreCase);

    private static int ValidateLanguageVersion(int? languageVersion, IReadOnlyList<string> targetFrameworks)
    {
        int minimum = TargetFrameworks.GetDefaultLanguageVersion(targetFrameworks);
        if (languageVersion is null)
        {
            return minimum;
        }

        if (languageVersion < minimum)
        {
            throw new CsComException(
                $"C# {languageVersion} is not supported for {string.Join(", ", targetFrameworks)}: C# {minimum} or later is required.");
        }

        return languageVersion.Value;
    }

    internal static void ValidateNamespace(string @namespace)
    {
        if (string.IsNullOrWhiteSpace(@namespace) || !@namespace.Split('.').All(static part => SyntaxFacts.IsValidIdentifier(part) && SyntaxFacts.GetKeywordKind(part) == SyntaxKind.None))
        {
            throw new CsComException($"'{@namespace}' is not a valid namespace.");
        }
    }

    private static string? FindProjectFile(string directory, string name)
    {
        string path = Path.Combine(directory, name + ".csproj");
        if (File.Exists(path))
        {
            return path;
        }

        var projects = Directory.GetFiles(directory, "*.csproj");
        return projects.Length == 1 ? projects[0] : null;
    }

    [LoggerMessage(Level = LogLevel.Information, Message = "Generated {Count} files in '{Directory}'")]
    private partial void LogFilesGenerated(int count, string directory);

    [LoggerMessage(Level = LogLevel.Information, Message = "Created the project '{Path}'")]
    private partial void LogProjectCreated(string path);

    [LoggerMessage(Level = LogLevel.Information, Message = "Updated the project '{Directory}' with {Count} generated files")]
    private partial void LogProjectUpdated(string directory, int count);

    [LoggerMessage(Level = LogLevel.Information, Message = "Updated the project file '{Path}'")]
    private partial void LogProjectFileUpdated(string path);

    [LoggerMessage(Level = LogLevel.Warning, Message = "No project file was found in '{Directory}'; only the generated files were updated")]
    private partial void LogProjectFileNotFound(string directory);

    [LoggerMessage(Level = LogLevel.Warning, Message = "The project uses central package management ({Path}): add <PackageVersion Include=\"{Package}\" Version=\"{Version}\" /> to it")]
    private partial void LogCentralPackageManagement(string path, string package, string version);

    [LoggerMessage(Level = LogLevel.Warning, Message = "The target framework '{TargetFramework}' is not Windows-specific; COM interop only works on Windows")]
    private partial void LogNotWindowsSpecific(string targetFramework);

    [LoggerMessage(Level = LogLevel.Warning, Message = "The runtime identifier '{RuntimeIdentifier}' is not a Windows runtime; COM interop only works on Windows")]
    private partial void LogNotWindowsRuntime(string runtimeIdentifier);
}

/// <summary>
/// The code of a new or updated project: the settings, the generated files and the root namespace, the namespace of the first source.
/// </summary>
internal sealed record GeneratedProject(CsComManifest Manifest, IReadOnlyList<GeneratedDocument> Documents, string RootNamespace, LibrarySetResult Result);
